import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Button,
  Grid,
  Alert,
  CircularProgress,
  Autocomplete,
  TextField,
  Avatar,
} from "@mui/material";
import axios from "axios";
import Swal from "sweetalert2";
import ModalEdicion from "./ModalEdicion";

const HistoriaClinicaTab = ({ cliente }) => {
  const [pacientes, setPacientes] = useState([]);
  const [selectedPaciente, setSelectedPaciente] = useState(null);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [openModal, setOpenModal] = useState(false);

  // Cargar pacientes
  useEffect(() => {
    const fetchPacientes = async () => {
      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get("/api/pacientes");
        setPacientes(res.data);
      } catch (err) {
        console.error("Error al cargar pacientes:", err);
        setError("No se pudieron cargar los pacientes");
        Swal.fire("Error", "No se pudieron cargar los pacientes", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchPacientes();
  }, []);

  // Cargar datos de historia clínica cuando se selecciona un paciente
  useEffect(() => {
    const fetchDatosHistoria = async () => {
      if (!selectedPaciente) return;

      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get(`/api/historia-clinica/${selectedPaciente.id}`);
        setData(res.data);
      } catch (err) {
        console.error("Error al cargar datos de historia clínica:", err);
        setError("No se pudieron cargar los datos de historia clínica");
        Swal.fire("Error", "No se pudieron cargar los datos de historia clínica", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchDatosHistoria();
  }, [selectedPaciente]);

  const handleEditar = () => {
    if (!selectedPaciente) {
      Swal.fire("Error", "Por favor selecciona un paciente", "error");
      return;
    }
    setOpenModal(true);
  };

  const handleImprimir = () => {
    Swal.fire({
      title: "Imprimir planilla",
      text: "¿Deseas imprimir la historia clínica?",
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Sí, imprimir",
      cancelButtonText: "Cancelar",
    }).then((result) => {
      if (result.isConfirmed) {
        // Aquí iría la lógica de impresión o PDF
        Swal.fire("Imprimiendo", "Generando PDF...", "info");
      }
    });
  };

  const handleCloseModal = () => {
    setOpenModal(false);
  };

  // Datos para el modal (estructurados para que el modal los mapee)
  const datosParaEditar = {
    paciente: selectedPaciente ? {
      nombreCompleto: selectedPaciente.nombre || "",
      dni: selectedPaciente.dni || "",
      fechaNacimiento: selectedPaciente.fechaNacimiento || "",
      edad: selectedPaciente.edad || "",
      os: selectedPaciente.os || "",
      afNumero: selectedPaciente.afNumero || "",
      fechaIngreso: selectedPaciente.fechaIngreso || "",
    } : {},
    funcional: data?.funcional || {
      camina: "",
      levantateYAnda: "",
      articulaciones: "",
      pasaMuchoTiempoSentado: "",
      equilibrio: "",
      caidas: "",
    },
    social: data?.social || {
      conQuienVive: "",
      hijos: "",
      concurreALaConsulta: "",
      conyuge: "",
      hermanos: "",
      acompanado: "",
      otros: "",
    },
    mental: data?.mental || {
      orientacionEnT: "",
      hijosMental: "",
      concurreALaConsultaMental: "",
      palabra1: "",
      palabra2: "",
      palabra3: "",
      calculo1: "",
      calculo2: "",
      calculo3: "",
      respuesta1: "",
      respuesta2: "",
      palabra1Memoria: "",
      palabra2Memoria: "",
      palabra3Memoria: "",
      respuestaRepita: "",
      textoLeido: "",
      cierreOjosYHagalo: "",
      logradoDoblePapel: "",
      logradoCopieDibujo: "",
      fraseEscrita: "",
    },
  };

  return (
    <Box>
      <Autocomplete
        disablePortal
        options={pacientes}
        getOptionLabel={(option) => option.nombre || ""}
        value={selectedPaciente}
        onChange={(event, newValue) => {
          setSelectedPaciente(newValue);
        }}
        renderInput={(params) => (
          <TextField {...params} label="Seleccionar paciente" variant="outlined" />
        )}
        sx={{ mb: 3, maxWidth: 400 }}
      />

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {loading && (
        <Box display="flex" justifyContent="center" my={4}>
          <CircularProgress />
        </Box>
      )}

      {selectedPaciente && data && !loading && (
        <Box>
          {/* Información del paciente */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Typography variant="h6">Información</Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <Typography variant="body2">Fecha de ingreso:</Typography>
                <Typography variant="body2">Nombre completo:</Typography>
                <Typography variant="body2">Os:</Typography>
                <Typography variant="body2">DNI:</Typography>
              </Grid>
              <Grid item xs={12} md={4}>
                <Typography variant="body2">Fecha de nacimiento:</Typography>
                <Typography variant="body2">Edad:</Typography>
                <Typography variant="body2">AF N°:</Typography>
              </Grid>
              <Grid item xs={12} md={4} display="flex" justifyContent="center" alignItems="center">
                <Avatar
                  src={selectedPaciente.foto || "/default-avatar.png"}
                  alt={selectedPaciente.nombre || "Paciente"}
                  sx={{ width: 92, height: 92 }}
                />
              </Grid>
            </Grid>
          </Paper>

          {/* Funcional */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Typography variant="h6">Funcional</Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Typography variant="body2">Camina:</Typography>
                <Typography variant="body2">Levántate y anda:</Typography>
                <Typography variant="body2">Articulaciones:</Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="body2">Pasa mucho tiempo sentado:</Typography>
                <Typography variant="body2">Equilibrio:</Typography>
                <Typography variant="body2">Caídas:</Typography>
              </Grid>
            </Grid>
          </Paper>

          {/* Social */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Typography variant="h6">Social</Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <Typography variant="body2">Con quién vive:</Typography>
                <Typography variant="body2">Hijos:</Typography>
                <Typography variant="body2">Concurre a la consulta:</Typography>
              </Grid>
              <Grid item xs={12} md={4}>
                <Typography variant="body2">Cónyuge:</Typography>
                <Typography variant="body2">Hermanos:</Typography>
                <Typography variant="body2">Acompañado:</Typography>
              </Grid>
              <Grid item xs={12} md={4}>
                <Typography variant="body2">Otros:</Typography>
              </Grid>
            </Grid>
          </Paper>

          {/* Mental */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Typography variant="h6">Mental</Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Orientación en T y E:
                </Typography>
                <Typography variant="body2">Hijos:</Typography>
                <Typography variant="body2">Concurre a la consulta:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Fijación (repita 3 palabras)
                </Typography>
                <Typography variant="body2">Palabra 1:</Typography>
                <Typography variant="body2">Palabra 2:</Typography>
                <Typography variant="body2">Palabra 3:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Concentración y cálculo
                </Typography>
                <Typography variant="body2">Cálculo 1:</Typography>
                <Typography variant="body2">Cálculo 2:</Typography>
                <Typography variant="body2">Cálculo 3:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  ¿Qué es esto?
                </Typography>
                <Typography variant="body2">Respuesta 1:</Typography>
                <Typography variant="body2">Respuesta 2:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Memoria (3 palabras)
                </Typography>
                <Typography variant="body2">Palabra 1:</Typography>
                <Typography variant="body2">Palabra 2:</Typography>
                <Typography variant="body2">Palabra 3:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Repita
                </Typography>
                <Typography variant="body2">Respuesta:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Lea esto
                </Typography>
                <Typography variant="body2">Texto leído:</Typography>
                <Typography variant="body2">Cierre los ojos y hágalo:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Doble papel
                </Typography>
                <Typography variant="body2">Logrado:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Copie dibujo
                </Typography>
                <Typography variant="body2">Logrado:</Typography>
              </Grid>
              <Grid item xs={12} md={2}>
                <Typography variant="subtitle2" sx={{ textDecoration: "underline" }}>
                  Escriba frase
                </Typography>
                <Typography variant="body2">Frase escrita:</Typography>
              </Grid>
            </Grid>
          </Paper>

          <Box display="flex" justifyContent="center" mt={3} gap={2}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={handleEditar}
            >
              Editar Contenido
            </Button>
            <Button
              variant="contained"
              color="warning"
              size="large"
              onClick={handleImprimir}
              sx={{ backgroundColor: "#ed6c02", "&:hover": { backgroundColor: "#e65100" } }}
            >
              Imprimir planilla
            </Button>
          </Box>

          {/* Modal de edición */}
          {openModal && (
            <ModalEdicion
              open={openModal}
              onClose={handleCloseModal}
              datos={datosParaEditar}
            />
          )}
        </Box>
      )}
    </Box>
  );
};

export default HistoriaClinicaTab;