import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Button,
  Grid,
  Alert,
  CircularProgress,
  Autocomplete,
  TextField,
} from "@mui/material";
import axios from "axios";
import Swal from "sweetalert2";
import ModalEdicion from "./ModalEdicion";

const FliaYApodTab = ({ cliente }) => {
  const [pacientes, setPacientes] = useState([]);
  const [selectedPaciente, setSelectedPaciente] = useState(null);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [openModal, setOpenModal] = useState(false);

  // Cargar pacientes
  useEffect(() => {
    const fetchPacientes = async () => {
      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get("/api/pacientes");
        setPacientes(res.data);
      } catch (err) {
        console.error("Error al cargar pacientes:", err);
        setError("No se pudieron cargar los pacientes");
        Swal.fire("Error", "No se pudieron cargar los pacientes", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchPacientes();
  }, []);

  // Cargar datos de flia y apoderados cuando se selecciona un paciente
  useEffect(() => {
    const fetchDatosFliaYApod = async () => {
      if (!selectedPaciente) return;

      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get(`/api/flia-apod/${selectedPaciente.id}`);
        setData(res.data);
      } catch (err) {
        console.error("Error al cargar datos de flia y apoderados:", err);
        setError("No se pudieron cargar los datos de flia y apoderados");
        Swal.fire("Error", "No se pudieron cargar los datos de flia y apoderados", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchDatosFliaYApod();
  }, [selectedPaciente]);

  const handleEditar = () => {
    if (!selectedPaciente) {
      Swal.fire("Error", "Por favor selecciona un paciente", "error");
      return;
    }
    setOpenModal(true);
  };

  const handleImprimir = () => {
    Swal.fire({
      title: "Imprimir planilla",
      text: "¿Deseas imprimir la planilla de información familiar y apoderados?",
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Sí, imprimir",
      cancelButtonText: "Cancelar",
    }).then((result) => {
      if (result.isConfirmed) {
        // Aquí iría la lógica de impresión o PDF
        Swal.fire("Imprimiendo", "Generando PDF...", "info");
      }
    });
  };

  const handleCloseModal = () => {
    setOpenModal(false);
  };

  // Datos para el modal (estructurados para que el modal los mapee)
  const datosParaEditar = {
    paciente: selectedPaciente ? {
      nombreCompleto: selectedPaciente.nombre || "",
      dni: selectedPaciente.dni || "",
    } : {},
    informacionAdicional: data?.informacionAdicional || {
      yo: "",
      dniNumero: "",
      calidad: "",
      residenteNombre: "",
      textoConsentimiento: "Que se encuentra ingresado en esta Residencia, ha sido informado/a de la medida de sujeción que se realiza bajo preescripción médica y dado el estado de salud de mi familiar/apoderante, es necesaria para evitar complicaciones graves tales como lesiones y/o caídas",
    },
  };

  return (
    <Box>
      <Autocomplete
        disablePortal
        options={pacientes}
        getOptionLabel={(option) => option.nombre || ""}
        value={selectedPaciente}
        onChange={(event, newValue) => {
          setSelectedPaciente(newValue);
        }}
        renderInput={(params) => (
          <TextField {...params} label="Seleccionar paciente" variant="outlined" />
        )}
        sx={{ mb: 3, maxWidth: 400 }}
      />

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {loading && (
        <Box display="flex" justifyContent="center" my={4}>
          <CircularProgress />
        </Box>
      )}

      {selectedPaciente && data && !loading && (
        <Box>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Paper sx={{ p: 2 }}>
                <Box
                  display="flex"
                  justifyContent="space-between"
                  alignItems="center"
                  mb={2}
                >
                  <Typography variant="h6">Información adicional</Typography>
                </Box>
                <Box sx={{ backgroundColor: "#ffffff", boxShadow: "0 8px 16px rgba(0, 0, 0, 0.08)", p: 1, borderRadius: "4px" }}>
                  <Typography variant="body2">Yo:</Typography>
                  <Box display="flex" alignItems="center" gap={6} mt={1}>
                    <Typography variant="body2">Identificado/a con DNI N°:</Typography>
                    <Typography variant="body2">y en calidad de:</Typography>
                  </Box>
                  <Typography variant="body2" mt={1}>Del residente Sr/Sra:</Typography>
                </Box>
              </Paper>
            </Grid>

            <Grid item xs={12} md={6}>
              <Paper sx={{ p: 2 }}>
                <Box
                  display="flex"
                  justifyContent="space-between"
                  alignItems="center"
                  mb={2}
                >
                  <Typography variant="h6">Información adicional</Typography>
                </Box>
                <Box sx={{ backgroundColor: "#ffffff", boxShadow: "0 8px 16px rgba(0, 0, 0, 0.08)", p: 1, borderRadius: "4px" }}>
                  <Typography variant="body2">
                    Que se encuentra ingresado en esta Residencia, ha sido informado/a de la medida de sujeción que se realiza bajo preescripción médica y dado el estado de salud de mi familiar/apoderante, es necesaria para evitar complicaciones graves tales como lesiones y/o caídas
                  </Typography>
                </Box>
              </Paper>
            </Grid>
          </Grid>

          <Box display="flex" justifyContent="center" mt={3} gap={2}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={handleEditar}
            >
              Editar Contenido
            </Button>
            <Button
              variant="contained"
              color="warning"
              size="large"
              onClick={handleImprimir}
              sx={{ backgroundColor: "#ed6c02", "&:hover": { backgroundColor: "#e65100" } }}
            >
              Imprimir planilla
            </Button>
          </Box>

          {/* Modal de edición */}
          {openModal && (
            <ModalEdicion
              open={openModal}
              onClose={handleCloseModal}
              datos={datosParaEditar}
            />
          )}
        </Box>
      )}
    </Box>
  );
};

export default FliaYApodTab;