import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Button,
  Grid,
  Alert,
  CircularProgress,
  Autocomplete,
  TextField,
} from "@mui/material";
import axios from "axios";
import Swal from "sweetalert2";
import ModalEdicion from "./ModalEdicion";

const ResumenHCTab = ({ cliente }) => {
  const [pacientes, setPacientes] = useState([]);
  const [selectedPaciente, setSelectedPaciente] = useState(null);
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [openModal, setOpenModal] = useState(false);

  // Cargar pacientes
  useEffect(() => {
    const fetchPacientes = async () => {
      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get("/api/pacientes");
        setPacientes(res.data);
      } catch (err) {
        console.error("Error al cargar pacientes:", err);
        setError("No se pudieron cargar los pacientes");
        Swal.fire("Error", "No se pudieron cargar los pacientes", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchPacientes();
  }, []);

  // Cargar datos de resumen HC cuando se selecciona un paciente
  useEffect(() => {
    const fetchDatosResumenHC = async () => {
      if (!selectedPaciente) return;

      try {
        setLoading(true);
        // Cambia esta URL por la real cuando tengas el backend
        const res = await axios.get(`/api/resumen-hc/${selectedPaciente.id}`);
        setData(res.data);
      } catch (err) {
        console.error("Error al cargar datos de resumen HC:", err);
        setError("No se pudieron cargar los datos de resumen HC");
        Swal.fire("Error", "No se pudieron cargar los datos de resumen HC", "error");
      } finally {
        setLoading(false);
      }
    };
    fetchDatosResumenHC();
  }, [selectedPaciente]);

  const handleEditar = () => {
    if (!selectedPaciente) {
      Swal.fire("Error", "Por favor selecciona un paciente", "error");
      return;
    }
    setOpenModal(true);
  };

  const handleImprimir = () => {
    Swal.fire({
      title: "Imprimir planilla",
      text: "¿Deseas imprimir el resumen de historia clínica?",
      icon: "question",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Sí, imprimir",
      cancelButtonText: "Cancelar",
    }).then((result) => {
      if (result.isConfirmed) {
        // Aquí iría la lógica de impresión o PDF
        Swal.fire("Imprimiendo", "Generando PDF...", "info");
      }
    });
  };

  const handleCloseModal = () => {
    setOpenModal(false);
  };

  // Datos para el modal (estructurados para que el modal los mapee)
  const datosParaEditar = {
    paciente: selectedPaciente ? {
      fecha: selectedPaciente.fecha || "",
      nombreCompleto: selectedPaciente.nombre || "",
      os: selectedPaciente.os || "",
      dni: selectedPaciente.dni || "",
      edad: selectedPaciente.edad || "",
      afNumero: selectedPaciente.afNumero || "",
    } : {},
    enfermedadBase: data?.enfermedadBase || {
      texto: "Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!",
      ultimaActualizacion: data?.ultimaActualizacion || "",
    },
    enfermedadActual: data?.enfermedadActual || {
      texto: "Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!",
      ultimaActualizacion: data?.ultimaActualizacion || "",
    },
    tratamientoBase: data?.tratamientoBase || {
      texto: "Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!",
      ultimaActualizacion: data?.ultimaActualizacion || "",
    },
  };

  return (
    <Box>
      <Autocomplete
        disablePortal
        options={pacientes}
        getOptionLabel={(option) => option.nombre || ""}
        value={selectedPaciente}
        onChange={(event, newValue) => {
          setSelectedPaciente(newValue);
        }}
        renderInput={(params) => (
          <TextField {...params} label="Seleccionar paciente" variant="outlined" />
        )}
        sx={{ mb: 3, maxWidth: 400 }}
      />

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      {loading && (
        <Box display="flex" justifyContent="center" my={4}>
          <CircularProgress />
        </Box>
      )}

      {selectedPaciente && data && !loading && (
        <Box>
          {/* Información del paciente */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Typography variant="h6">Paciente</Typography>
            </Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Typography variant="body2">Fecha:</Typography>
                <Typography variant="body2">Nombre completo:</Typography>
                <Typography variant="body2">Os:</Typography>
              </Grid>
              <Grid item xs={12} md={6}>
                <Typography variant="body2">Dni:</Typography>
                <Typography variant="body2">Edad:</Typography>
                <Typography variant="body2">AF N°:</Typography>
              </Grid>
            </Grid>
          </Paper>

          {/* Enfermedad de base */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Box display="flex" alignItems="center">
                <Typography variant="h6" component="span">
                  Enfermedad de base -
                </Typography>
                <Typography variant="subtitle2" component="span" ml={1}>
                  última fecha de actualización
                </Typography>
              </Box>
            </Box>
            <Box sx={{ backgroundColor: "#ffffff", boxShadow: "0 8px 16px rgba(0, 0, 0, 0.08)", p: 1, borderRadius: "4px" }}>
              <Typography variant="body2">
                Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!
              </Typography>
            </Box>
          </Paper>

          {/* Enfermedad actual */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Box display="flex" alignItems="center">
                <Typography variant="h6" component="span">
                  Enfermedad actual -
                </Typography>
                <Typography variant="subtitle2" component="span" ml={1}>
                  última fecha de actualización
                </Typography>
              </Box>
            </Box>
            <Box sx={{ backgroundColor: "#ffffff", boxShadow: "0 8px 16px rgba(0, 0, 0, 0.08)", p: 1, borderRadius: "4px" }}>
              <Typography variant="body2">
                Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!
              </Typography>
            </Box>
          </Paper>

          {/* Tratamiento de base */}
          <Paper sx={{ p: 2, mb: 3 }}>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="center"
              mb={2}
            >
              <Box display="flex" alignItems="center">
                <Typography variant="h6" component="span">
                  Tratamiento de base -
                </Typography>
                <Typography variant="subtitle2" component="span" ml={1}>
                  última fecha de actualización
                </Typography>
              </Box>
            </Box>
            <Box sx={{ backgroundColor: "#ffffff", boxShadow: "0 8px 16px rgba(0, 0, 0, 0.08)", p: 1, borderRadius: "4px" }}>
              <Typography variant="body2">
                Lorem ipsum dolor sit, amet consectetur adipisicing elit. Velit, quo dolorem dignissimos veniam quos adipisci ab dolor maiores delectus voluptates! Maiores, placeat ullam perspiciatis asperiores amet atque adipisci labore minima!
              </Typography>
            </Box>
          </Paper>

          <Box display="flex" justifyContent="center" mt={3} gap={2}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={handleEditar}
            >
              Editar Contenido
            </Button>
            <Button
              variant="contained"
              color="warning"
              size="large"
              onClick={handleImprimir}
              sx={{ backgroundColor: "#ed6c02", "&:hover": { backgroundColor: "#e65100" } }}
            >
              Imprimir planilla
            </Button>
          </Box>

          {/* Modal de edición */}
          {openModal && (
            <ModalEdicion
              open={openModal}
              onClose={handleCloseModal}
              datos={datosParaEditar}
            />
          )}
        </Box>
      )}
    </Box>
  );
};

export default ResumenHCTab;